'use strict';
const variant = document.body.dataset.variant;
const $ = s => document.querySelector(s);
const icons = {
 map:'<circle cx="5" cy="12" r="3"/><rect x="15" y="3" width="6" height="5" rx="1.5"/><rect x="15" y="16" width="6" height="5" rx="1.5"/><path d="M8 12h3m0 0V5.5h4M11 12v6.5h4"/>',
 code:'<path d="m8 7-5 5 5 5m8-10 5 5-5 5m-3-14-2 18"/>',
 plus:'<path d="M12 5v14M5 12h14"/>', minus:'<path d="M5 12h14"/>',
 edit:'<path d="m15 5 4 4M4 20l4-1L20 7a2.8 2.8 0 0 0-4-4L4 15z"/>',
 child:'<path d="M5 3v10a3 3 0 0 0 3 3h10m-4-4 4 4-4 4"/>',
 sibling:'<path d="M4 6h16M12 12v8m-4-4h8"/>',
 download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v4h16v-4"/>',
 moon:'<path d="M20.5 13A8.5 8.5 0 0 1 11 3.5 8.5 8.5 0 1 0 20.5 13Z"/>',
 sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',
 chevron:'<path d="m9 5 7 7-7 7"/>',undo:'<path d="m8 4-5 5 5 5M3 9h10a7 7 0 0 1 0 14"/>',redo:'<path d="m16 4 5 5-5 5m5-5H11a7 7 0 0 0 0 14"/>',
 fit:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m8 0h5v-5"/>',
 book:'<path d="M12 5v16M3 3c4-1 7 0 9 2 2-2 5-3 9-2v15c-4-1-7 0-9 2-2-2-5-3-9-2z"/>',
 run:'<circle cx="15" cy="4" r="2"/><path d="m8 9 4-2 4 5 4 1m-9-4-2 6 5 2 1 5M9 15l-5 5"/>',
 flag:'<path d="M5 21V4c5-5 9 5 14 0v10c-5 5-9-5-14 0"/>',
 spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',
 leaf:'<path d="M20 3C5 1 1 12 7 17s16-1 13-14ZM6 20 17 8"/>',
 arrow:'<path d="M12 19V5m-5 5 5-5 5 5"/>'
};
const icon = (name) => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.spark}</svg>`;
const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const make = (title, children = []) => ({id:crypto.randomUUID ? crypto.randomUUID() : `node-${Date.now()}-${Math.random()}`,title,children});
const sample = () => make('人生',[
 make('学习',[make('语言学习',[make('英语口语'),make('日语入门')]),make('专业技能',[make('编程'),make('设计')]),make('阅读',[make('每月读一本书')])]),
 make('运动',[make('跑步',[make('完成一次半马')]),make('力量训练'),make('户外徒步')]),
 make('要做的事',[make('去看一次极光'),make('学会一道拿手菜'),make('记录生活')]),
 make('生活',[make('家人与朋友'),make('身心健康')])
]);
const key = `aio-life-mindmap-prototype-${variant}-v1`;
let root = sample(), selected, focus, mode = 'map', zoom = .8, collapsed = new Set(), undoStack = [], redoStack = [], mdTimer, toastTimer, editAction;
let storageReady = true;
try {const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved && typeof saved.markdown==='string')root=parseMarkdown(saved.markdown);} catch {storageReady=false;}
selected=root.children[0]?.id || root.id;focus=root.id;
collapsed=new Set(root.children.flatMap(c=>c.children.map(n=>n.id)));
let canvasExpanded=new Set([root.id,selected]);
function visibleChildren(n){return n.id===root.id||canvasExpanded.has(n.id)?n.children:[];}
const palette = ['#75a58b','#a28bc0','#c29a6e','#7b9eb6'];
function allNodes(n=root){return [n,...n.children.flatMap(c=>allNodes(c))];}
function find(id,n=root){if(n.id===id)return n;for(const c of n.children){const hit=find(id,c);if(hit)return hit;}return null;}
function parentOf(id,n=root){for(const c of n.children){if(c.id===id)return n;const hit=parentOf(id,c);if(hit)return hit;}return null;}
function pathTo(id){let n=find(id),path=[];while(n){path.unshift(n);n=parentOf(n.id);}return path;}
function toMarkdown(n=root){let lines=[`# ${n.title}`,''];function walk(node,depth){lines.push(`${'  '.repeat(depth)}- ${node.title}`);node.children.forEach(c=>walk(c,depth+1));}n.children.forEach(c=>walk(c,0));return lines.join('\n')+'\n';}
function parseMarkdown(text){const lines=text.replace(/\r/g,'').split('\n');let result=null;const stack=[];for(let i=0;i<lines.length;i++){const line=lines[i];if(!line.trim())continue;if(!result){const title=line.match(/^# +(.+)$/);if(!title)throw Error(`第 ${i+1} 行：请以 # 人生 这样的一级标题开始`);if(title[1].trim().length>80)throw Error('标题最多 80 个字');result=make(title[1].trim());stack[0]=result;continue;}const match=line.match(/^( *)(?:-|\*|\+) +(.+)$/);if(!match || match[1].length%2)throw Error(`第 ${i+1} 行：使用 - 分类，每级缩进两个空格`);const depth=match[1].length/2;if(depth>=30)throw Error(`第 ${i+1} 行：最多支持 30 层分类`);if(!stack[depth])throw Error(`第 ${i+1} 行：缩进不能跳过层级`);if(match[2].trim().length>80)throw Error(`第 ${i+1} 行：分类名称最多 80 个字`);const node=make(match[2].trim());stack[depth].children.push(node);stack[depth+1]=node;stack.length=depth+2;}if(!result)throw Error('请先输入 # 人生 这样的一级标题');if(allNodes(result).length>500)throw Error('当前原型最多支持 500 个节点');return result;}
function remember(){undoStack.push(JSON.stringify(root));if(undoStack.length>50)undoStack.shift();redoStack=[];}
function persist(){try{localStorage.setItem(key,JSON.stringify({markdown:toMarkdown()}));storageReady=true;$('.saved').textContent='已存到此设备';}catch{storageReady=false;$('.saved').textContent='暂未保存';}updateCounts();}
function updateCounts(){$('.count').textContent=`${allNodes().length} 个节点`;$('#undo').disabled=!undoStack.length;$('#redo').disabled=!redoStack.length;}
function toast(msg){clearTimeout(toastTimer);$('.toast').textContent=msg;$('.toast').hidden=false;toastTimer=setTimeout(()=>$('.toast').hidden=true,2500);}
function updateSelection(){if(!find(selected))selected=root.id;const n=find(selected);$('.selected-name').textContent=n.title;$('.selection-info small').textContent=`当前节点 · ${n.children.length} 个下级`;$('#quick-label').textContent=`添加到「${n.title}」下面`;$('#quick').placeholder=`添加到「${n.title}」…`;$('#add-sibling').disabled=n.id===root.id;}
function render(){updateCounts();updateSelection();$('#map-panel').hidden=mode!=='map';$('#md-panel').hidden=mode!=='md';$('.selection').hidden=mode!=='map';$('#quick-form').hidden=mode!=='map';$('.segments').querySelectorAll('button').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.mode===mode)));if(mode==='map'){if(variant==='canvas')renderCanvas();else if(variant==='tree')renderTree();else renderFocus();}else $('#md-editor').value=toMarkdown();}
function choose(id){selected=id;updateSelection();if(variant==='canvas')document.querySelectorAll('.node').forEach(b=>b.classList.toggle('selected',b.dataset.id===id));else if(variant==='tree')document.querySelectorAll('.tree-row').forEach(b=>b.classList.toggle('selected',b.dataset.id===id));}
function renderCanvas(){const panel=$('#map-panel');const old=panel.querySelector('.map-viewport');const pos=old?{x:old.scrollLeft,y:old.scrollTop}:null;const positions=[];let cursor=35;const nodeWidth=132,nodeHeight=48,stepX=181;function layout(n,depth,color){const start=cursor;let y;if(visibleChildren(n).length){const ys=visibleChildren(n).map(c=>layout(c,depth+1,color));y=(ys[0]+ys[ys.length-1])/2;}else{y=cursor;cursor+=72;}positions.push({n,x:30+depth*stepX,y,depth,color});return y;}const branchYs=root.children.map((c,i)=>layout(c,1,palette[i%4]));let rootY=branchYs.length?(branchYs[0]+branchYs.at(-1))/2:100;positions.push({n:root,x:30,y:rootY,depth:0,color:palette[0]});const lookup=new Map(positions.map(p=>[p.n.id,p]));const width=Math.max(680,...positions.map(p=>p.x+nodeWidth+40)),height=Math.max(cursor+30,350);let paths='';positions.forEach(p=>visibleChildren(p.n).forEach(child=>{const c=lookup.get(child.id);const x1=p.x+nodeWidth,x2=c.x,y1=p.y+nodeHeight/2,y2=c.y+nodeHeight/2;paths+=`<path d="M${x1} ${y1} C${x1+30} ${y1},${x2-32} ${y2},${x2} ${y2}" fill="none" stroke="${c.color}" stroke-width="1.5" opacity=".65"/>`;}));panel.innerHTML=`<div class="map-viewport" tabindex="0" role="region" aria-label="思维导图画布，可横向和纵向滚动"><div class="map-sizer" style="width:${width*zoom}px;height:${height*zoom}px"><div class="map-inner" style="width:${width}px;height:${height}px;transform:scale(${zoom})"><svg class="mind-svg" width="${width}" height="${height}" aria-hidden="true">${paths}</svg>${positions.map(p=>`<button class="node ${p.depth===0?'root':''} ${p.n.id===selected?'selected':''}" data-id="${p.n.id}" style="left:${p.x}px;top:${p.y}px;width:${nodeWidth}px;min-height:${nodeHeight}px;--node-color:${p.color}" aria-label="选择 ${esc(p.n.title)}">${esc(p.n.title)}${p.n.children.length?`<small>${canvasExpanded.has(p.n.id)||p.n.id===root.id?"−":"+"}</small>`:""}</button>`).join('')}</div></div></div><span class="canvas-tip">滑动画布 · 点选节点</span><div class="map-tools"><button class="icon-button" data-zoom="out" aria-label="缩小">${icon('minus')}</button><span class="zoom-label">${Math.round(zoom*100)}%</span><button class="icon-button" data-zoom="in" aria-label="放大">${icon('plus')}</button><button class="icon-button" data-zoom="fit" aria-label="查看全图">${icon('fit')}</button></div>`;panel.querySelectorAll('.node').forEach(b=>b.onclick=()=>{choose(b.dataset.id);if(find(selected).children.length&&selected!==root.id){canvasExpanded.has(selected)?canvasExpanded.delete(selected):canvasExpanded.add(selected);renderCanvas();}});panel.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{if(b.dataset.zoom==='fit'){zoom=Math.max(.2,Math.min((panel.clientWidth-30)/width,(panel.clientHeight-30)/height,1));}else zoom=Math.max(.2,Math.min(1.6,zoom+(b.dataset.zoom==='in'?.15:-.15)));renderCanvas();});const viewport=panel.querySelector('.map-viewport');if(pos){viewport.scrollLeft=pos.x;viewport.scrollTop=pos.y;}else{viewport.scrollTop=Math.max(0,rootY*zoom-viewport.clientHeight/2+24);viewport.scrollLeft=0;} }
function renderTree(){const panel=$('#map-panel'),scroll=panel.querySelector('.tree-content')?.scrollTop||0;function row(n,depth,color){const has=n.children.length>0,open=!collapsed.has(n.id);return `<div class="tree-row depth-${depth} ${selected===n.id?'selected':''}" data-id="${n.id}" style="--node-color:${color}"><button class="collapse" data-collapse="${n.id}" ${has?`aria-expanded="${open}" aria-label="${open?'收起':'展开'} ${esc(n.title)}"`:'disabled aria-label="无下级分类"'}>${has?icon('chevron'):''}</button><span class="dot"></span><button class="label" data-select="${n.id}">${esc(n.title)}</button>${has?`<span class="row-count">${n.children.length}</span>`:''}</div>${has&&open?`<div class="tree-children">${n.children.map(c=>row(c,depth+1,color)).join('')}</div>`:''}`;}
panel.innerHTML=`<div class="tree-content"><div class="tree-root"><span class="root-icon">${icon('leaf')}</span><div><strong>${esc(root.title)}</strong><small>每个想法，都有它的位置</small></div><button class="icon-button" id="tree-root-select" aria-label="选择根节点">${icon('edit')}</button></div>${root.children.map((c,i)=>`<section class="tree-group">${row(c,1,palette[i%4])}<button class="group-add" data-add="${c.id}">${icon('plus')}添加到${esc(c.title)}</button></section>`).join('')}<button class="focus-add" data-add="${root.id}">${icon('plus')}添加一级分类</button></div>`;panel.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>choose(b.dataset.select));panel.querySelectorAll('[data-collapse]').forEach(b=>b.onclick=()=>{const id=b.dataset.collapse;collapsed.has(id)?collapsed.delete(id):collapsed.add(id);renderTree();});panel.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{choose(b.dataset.add);openEdit('child');});$('#tree-root-select').onclick=()=>{choose(root.id);openEdit('rename');};panel.querySelector('.tree-content').scrollTop=scroll;}
function renderFocus(){const panel=$('#map-panel');if(!find(focus))focus=root.id;const n=find(focus),path=pathTo(focus);selected=focus;updateSelection();panel.innerHTML=`<div class="focus-panel"><nav class="breadcrumb" aria-label="分类路径">${path.map((p,i)=>`${i?icon('chevron'):''}<button data-focus="${p.id}" ${i===path.length-1?'aria-current="page"':''}>${esc(p.title)}</button>`).join('')}</nav><div class="focus-hero"><span class="orbit-symbol">${icon(n.id===root.id?'spark':'book')}</span><h2>${esc(n.title)}</h2><p>${n.id===root.id?'让零散的念头，慢慢长成方向':`${path.length-1} 层深入 · ${n.children.length} 个分支`}</p></div><div class="focus-link"></div><div class="focus-list">${n.children.map((c,i)=>`<button class="focus-card" data-focus="${c.id}" style="--node-color:${palette[i%4]}"><span class="category-icon">${icon(['book','run','flag','leaf'][i%4])}</span><span class="card-label"><strong>${esc(c.title)}</strong><small>${c.children.length?esc(c.children.map(x=>x.title).join(' · ')):'还没有下级分类，点此继续生长'}</small></span>${icon('chevron')}</button>`).join('')}</div>${!n.children.length?'<div class="focus-empty">到了一个新的起点<br>写下你的第一个想法</div>':''}<button class="focus-add" data-focus-add>${icon('plus')}添加一个分支</button></div>`;panel.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>{focus=b.dataset.focus;renderFocus();});panel.querySelector('[data-focus-add]').onclick=()=>openEdit('child');}
function openEdit(action){editAction=action;$('#delete-confirm').hidden=true;const n=find(selected);$('#edit-title').textContent=action==='rename'?'编辑分类':action==='sibling'?'添加同级分类':'添加下级分类';$('#edit-context').textContent=action==='sibling'?`放在「${parentOf(n.id)?.title}」下面`:`${action==='rename'?'当前分类':'添加到'}「${n.title}」`;$('#edit-name').value=action==='rename'?n.title:'';$('#delete-node').hidden=action!=='rename'||selected===root.id;$('#edit-dialog').showModal();$('#edit-name').focus();}
function addNode(title,parent){if(pathTo(parent.id).length>30){toast('当前原型最多支持 30 层分类');return false;}if(allNodes().length>=500){toast('当前原型最多支持 500 个节点');return false;}remember();const n=make(title);parent.children.push(n);collapsed.delete(parent.id);canvasExpanded.add(parent.id);selected=n.id;if(variant==='focus')focus=parent.id;persist();render();toast('已添加分类');return true;}
function applyMarkdown(){clearTimeout(mdTimer);try{const next=parseMarkdown($('#md-editor').value);if(toMarkdown(next)!==toMarkdown()){remember();root=next;selected=root.id;focus=root.id;canvasExpanded=new Set([root.id,root.children[0]?.id]);persist();}$('#md-status').textContent='导图已同步';$('#md-help').textContent='第一行 # 根分类；其余用 - 分类，每级缩进两个空格。';$('#md-help').classList.remove('error');return true;}catch(e){$('#md-status').textContent='格式待调整';$('#md-help').textContent=e.message;$('#md-help').classList.add('error');return false;}}
function setMode(next){if(next===mode)return;if(mode==='md'&&!applyMarkdown()){toast('请先修正 Markdown 格式，内容已保留');return;}mode=next;render();}
function historyMove(back){if(mode==='md'&&!applyMarkdown())return;const from=back?undoStack:redoStack,to=back?redoStack:undoStack;if(!from.length)return;to.push(JSON.stringify(root));root=JSON.parse(from.pop());canvasExpanded=new Set([root.id,root.children[0]?.id]);if(!find(selected))selected=root.id;if(!find(focus))focus=root.id;persist();render();}
const meta = {
canvas:{brand:'枝间',eyebrow:'A LITTLE SPACE FOR YOUR MIND',title:'把人生，<span>慢慢展开。</span>',sub:'想到什么，就种下一枝。让每个方向都清晰可见。',label:'01 · 自由画布'},
tree:{brand:'枝间 · 大纲',eyebrow:'ONE THOUGHT, ONE BRANCH',title:'想法有序，<br><span>生活有方向。</span>',sub:'从一个念头开始，整理属于自己的生活脉络。',label:'02 · 分类树'},
focus:{brand:'枝间 · 聚焦',eyebrow:'MAKE ROOM FOR WHAT MATTERS',title:'一次，<span>只想一件事。</span>',sub:'沿着好奇心，一层一层，找到想去的方向。',label:'03 · 逐层聚焦'}
}[variant];
$('.app').innerHTML=`<header class="topbar"><div class="brand"><span class="brand-mark">${icon('map')}</span>${meta.brand}</div><div class="top-actions"><span class="saved">${storageReady?'此设备保存':'暂未保存'}</span><button class="icon-button" id="theme" aria-label="切换深浅主题">${icon(variant==='focus'?'sun':'moon')}</button><button class="icon-button" id="export" aria-label="导出 Markdown">${icon('download')}</button></div></header><section class="heading"><div class="eyebrow"><span>✦</span>${meta.eyebrow}</div><h1>${meta.title}</h1><p class="subtitle">${meta.sub}</p></section><div class="modebar"><div class="segments" role="tablist" aria-label="编辑视图"><button role="tab" id="map-tab" aria-controls="map-panel" aria-selected="true" data-mode="map">${icon('map')}思维导图</button><button role="tab" id="md-tab" aria-controls="md-panel" aria-selected="false" data-mode="md">${icon('code')}Markdown</button></div><span class="count"></span></div><main class="workspace"><section id="map-panel" class="map-panel" role="tabpanel" aria-labelledby="map-tab"></section><section class="md-panel" id="md-panel" role="tabpanel" aria-labelledby="md-tab" hidden><div class="editor-top"><span>life-map.md</span><span id="md-status">导图已同步</span></div><textarea id="md-editor" aria-label="Markdown 分类编辑器" spellcheck="false" autocapitalize="off"></textarea><div class="md-help" id="md-help">第一行 # 根分类；其余用 - 分类，每级缩进两个空格。</div></section></main><section class="selection" aria-label="当前节点操作"><div class="selection-info"><small>当前节点</small><strong class="selected-name"></strong></div><div class="node-actions"><button class="icon-button" id="add-child" aria-label="添加下级分类" title="添加下级">${icon('child')}</button><button class="icon-button" id="add-sibling" aria-label="添加同级分类" title="添加同级">${icon('sibling')}</button><button class="icon-button" id="rename" aria-label="编辑当前分类" title="编辑分类">${icon('edit')}</button></div></section><form class="quick-area" id="quick-form"><div class="quick-input"><input id="quick" aria-labelledby="quick-label" maxlength="80" autocomplete="off" required><button type="submit" class="add-button" aria-label="添加分类">${icon('plus')}</button></div><p class="quick-note" id="quick-label"></p></form><footer class="footer"><span>${meta.label}</span><div><button id="undo" aria-label="撤销" style="padding:0 7px">↶</button><button id="redo" aria-label="重做" style="padding:0 7px">↷</button><a href="index.html" target="_top">全部方案 ↗</a></div></footer><div class="toast" role="status" hidden></div><dialog class="edit-dialog" id="edit-dialog" aria-labelledby="edit-title"><form id="edit-form"><h2 id="edit-title"></h2><p id="edit-context"></p><label for="edit-name">分类名称</label><input id="edit-name" maxlength="80" required autocomplete="off"><div class="dialog-actions"><button type="button" class="danger" id="delete-node">删除分类</button><button type="button" id="edit-cancel">取消</button><button type="submit" class="primary">保存</button></div><div class="delete-confirm" id="delete-confirm" hidden>将同时删除此分类下的所有节点。<br><button type="button" id="delete-do">确认删除</button></div></form></dialog>`;
$('.segments').querySelectorAll('button').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
$('.segments').onkeydown=e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();setMode(mode==='map'?'md':'map');$(`[data-mode="${mode}"]`).focus();}};
$('#quick-form').onsubmit=e=>{e.preventDefault();const title=$('#quick').value.trim();if(!title)return;if(addNode(title,find(selected)))$('#quick').value='';};
$('#add-child').onclick=()=>openEdit('child');$('#add-sibling').onclick=()=>openEdit('sibling');$('#rename').onclick=()=>openEdit('rename');$('#edit-cancel').onclick=()=>$('#edit-dialog').close();
$('#edit-form').onsubmit=e=>{e.preventDefault();const title=$('#edit-name').value.trim();if(!title){$('#edit-name').setCustomValidity('请输入分类名称');$('#edit-name').reportValidity();return;}if(editAction==='rename'){remember();find(selected).title=title;persist();render();}else if(!addNode(title,editAction==='sibling'?parentOf(selected):find(selected)))return;$('#edit-dialog').close();};
$('#edit-name').oninput=()=>$('#edit-name').setCustomValidity('');
$('#delete-node').onclick=()=>{$('#delete-confirm').hidden=!$('#delete-confirm').hidden;};$('#delete-do').onclick=()=>{const p=parentOf(selected);if(!p)return;remember();p.children=p.children.filter(c=>c.id!==selected);selected=p.id;focus=p.id;persist();render();$('#edit-dialog').close();toast('已删除，可撤销');};
$('#md-editor').oninput=()=>{clearTimeout(mdTimer);$('#md-status').textContent='正在同步…';mdTimer=setTimeout(applyMarkdown,450);};
$('#md-editor').onkeydown=e=>{if(e.key==='Tab'){e.preventDefault();const el=e.target,start=el.selectionStart,end=el.selectionEnd;el.setRangeText('  ',start,end,'end');el.dispatchEvent(new Event('input'));}};
$('#undo').onclick=()=>historyMove(true);$('#redo').onclick=()=>historyMove(false);
$('#theme').onclick=()=>{document.body.classList.toggle(variant==='focus'?'light-focus':'dark');};
$('#export').onclick=()=>{if(mode==='md'&&!applyMarkdown()){toast('请先修正 Markdown 格式');return;}const blob=new Blob([toMarkdown()],{type:'text/markdown;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='life-map.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出 Markdown');};
window.addEventListener('beforeunload',e=>{if(mode==='md'){try{parseMarkdown($('#md-editor').value);}catch{e.preventDefault();e.returnValue='';}}});
render();
